import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"中吕·红绣鞋次韵","description":"","frontmatter":{"title":"中吕·红绣鞋次韵","date":"2026-11-11T00:00:00.000Z","seq":4,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/中吕·红绣鞋次韵.md","filePath":"blogs/元曲·张可久/中吕·红绣鞋次韵.md"}'),o={name:"blogs/元曲·张可久/中吕·红绣鞋次韵.md"};function c(l,a,n,m,z,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="中吕·红绣鞋次韵" tabindex="-1">中吕·红绣鞋次韵 <a class="header-anchor" href="#中吕·红绣鞋次韵" aria-label="Permalink to &quot;中吕·红绣鞋次韵&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">剑击西风鬼啸，琴弹夜月猿号，半醉渊明可人招。</p><p class="poem-stanza">南来山隐隐，东去浪淘淘，浙江归路杳。</p><p class="poem-stanza">春日湖上二首百五日清明节假，两三攒绿暗人家，客子飘零尚天涯。</p><p class="poem-stanza">春风轻柳絮，夜雨瘦梨花，绿杨阴谁系马？绿树当门酒肆，红妆映水鬟儿，眼底殷勤座间诗。</p><p class="poem-stanza">尘埃三五字，杨柳万千丝，记年时曾到此。</p><p class="poem-stanza">春夜燕子来时酒病，牡丹开处诗情，庭院黄昏雨初晴。</p><p class="poem-stanza">镜心闲挂月，筝手碎弹冰，樽前春夜永。</p><p class="poem-stanza">湖上无是无非心事，不寒不暖花时，妆点西湖似西施。</p><p class="poem-stanza">控青丝玉面马，歌《金缕》粉团儿，信人生行乐耳。</p><p class="poem-stanza">圣水寺山亭佛国清凉境界，壶天金碧楼台，照眼西山画屏开。</p><p class="poem-stanza">海云推月上，江水带潮来，醉嫌天地窄。</p><p class="poem-stanza">越山即事山拥玉皇香案，烟笼翠羽仙鬟，两袖天风倚高寒。</p><p class="poem-stanza">鹤归苍树杪，犬吠白云间，蓬莱迷望眼。</p><p class="poem-stanza">天台瀑布寺绝顶峰攒雪剑，悬崖水挂冰帘，倚树哀猿弄云尖。</p><p class="poem-stanza">血华啼杜字，阴洞吼飞廉，比人心山未险。</p><p class="poem-stanza">次归去来韵东舍西邻酒债，春花秋月诗才，两字功名困尘埃。</p><p class="poem-stanza">青山依旧好，黄菊近新栽，没商量归去来。</p><p class="poem-stanza">洞庭道中二首白鹭荒堤老葑，黄云远水长空，百尺蒲帆饱西风。</p><p class="poem-stanza">酒旗花影里，钓艇树阴中，好山千万重。</p><p class="poem-stanza">逐名利长安日下，望乡关倦客天涯，孤雁南来倍思家。</p><p class="poem-stanza">乱山云掩翠，老树雪生花，冻吟诗骑瘦马。</p><p class="poem-stanza">天台桐柏山中谈世事渔樵闲问，洗征尘麋鹿相亲，步入蓬莱误寻真。</p><p class="poem-stanza">竹声摇翠雨，山影护苍云，神仙深处隐。</p><p class="poem-stanza">雪芳亭金错落樽前酒令，玉娉婷乐府新声，夜深花睡嫩寒生。</p><p class="poem-stanza">一围云锦树，四面雪芳亭，月斜时人未醒。</p><p class="poem-stanza">春晚圆旧梦衾闲锦绣，按新声弦断箜篌，满襟离思倦登楼。</p><p class="poem-stanza">花寒鹦鹉病，春去杜鹃愁，倚栏人困酒。</p><p class="poem-stanza">岁暮二首金莲步苍苔小径，玉钩垂翠竹闲亭，物换星移暗伤情。</p><p class="poem-stanza">游鱼翻冻影，啼鸟泛春声，落梅香暮景。</p><p class="poem-stanza">竞酒争花公事，吟风弄月神思，好春能有几何时？玲珑心似锦，积渐鬓成丝，落一张闲故纸。</p><p class="poem-stanza">山中黄叶青烟丹灶，曲阑明月诗巢，绿波亭下小红桥。</p><p class="poem-stanza">老梅盘鹤膝，新柳舞蛮腰，嫩茶舒凤爪。</p><p class="poem-stanza">鉴湖落叶山容消瘦，题诗人物风流，一片闲云驻行舟。</p><p class="poem-stanza">月寒清镜晓，花淡碧壶秋，谪仙同载酒。</p><p class="poem-stanza">三衢山中白酒黄柑山郡，短衣瘦马诗人，袖手观棋度青春。</p><p class="poem-stanza">仙桥藏老树，石笋瘗苍云，松花飘瑞粉。</p></div>',3)])])}const d=s(o,[["render",c]]);export{i as __pageData,d as default};
